// Load session context safely from Universal Webhook and Tenant Config
const webhookBody = $('Universal Webhook').first()?.json?.body || {};
const tenantId = webhookBody.tenant_id || '';
const customerId = webhookBody.customer_id || webhookBody.sender_phone || webhookBody.sender_jid || 'unknown';
const sessionKey = `session:${tenantId}:${customerId}`;
const config = $input.first()?.json?.data || {};

return [{
  json: {
    session_key: sessionKey,
    tenant_id: tenantId,
    customer_id: customerId,
    sender_phone: webhookBody.sender_phone || '',
    sender_jid: webhookBody.sender_jid || '',
    message: webhookBody.message || '',
    context: webhookBody.context || {},
    history: webhookBody.history || [],
    config: config
  }
}];

// Build dynamic prompt based on tenant config + RAG results
const session = $('Load Session').first()?.json || {};
const ragResults = $input.first()?.json || {};
const config = session.config || {};
const userMessage = session.message || $('Universal Webhook').first()?.json?.body?.message || '';

// Build context from RAG
let ragContext = '';
if (ragResults.data && Array.isArray(ragResults.data) && ragResults.data.length > 0) {
  ragContext = '\n\n=== INFORMASI BISNIS ===\n';
  for (const doc of ragResults.data) {
    ragContext += `- [${doc.source_type || 'info'}] ${doc.content}\n`;
  }
}

// Build conversation history
let historyText = '';
if (session.history && Array.isArray(session.history) && session.history.length > 0) {
  const maxMessages = config.max_context_messages || 10;
  const recentHistory = session.history.slice(-maxMessages);
  historyText = '\n\n=== RIWAYAT PERCAKAPAN ===\n';
  for (const msg of recentHistory) {
    historyText += `${msg.role}: ${msg.content}\n`;
  }
}

// System prompt
const systemPrompt = (config.system_prompt && config.system_prompt.trim()) ? config.system_prompt : 
  `Kamu adalah asisten CS AI untuk bisnis UMKM. Jawab pertanyaan pelanggan dengan ramah, jelas, dan ${config.tone || 'friendly'} dalam bahasa ${config.language === 'en' ? 'English' : 'Indonesia'}.`;

const fullPrompt = systemPrompt + ragContext + historyText;

return [{
  json: {
    system_prompt: fullPrompt,
    user_message: userMessage,
    tenant_id: session.tenant_id,
    customer_id: session.customer_id,
    channel: session.channel || 'whatsapp',
    llm_provider: config.llm_provider || 'minimax',
    llm_model: config.llm_model || 'MiniMax-M2.7',
    temperature: config.temperature || 0.7,
    max_tokens: config.max_tokens || 1024,
    fallback_message: config.fallback_message || 'Maaf, saya belum bisa menjawab pertanyaan tersebut. Silakan hubungi admin toko.',
    config: config
  }
}];

