// Check if escalation is needed
const promptData = $('Prompt Builder').first()?.json || {};
const config = promptData.config || {};
const userMessage = (promptData.user_message || '').toLowerCase();
const aiResponse = $('LLM Call').first()?.json || {};

let shouldEscalate = false;
let reason = '';

// 1. Keyword-based escalation
const keywords = config.escalation_keywords || ['bicara cs', 'hubungi admin', 'operator', 'manusia', 'human', 'bantuan cs'];
for (const kw of keywords) {
  if (userMessage.includes(kw.toLowerCase())) {
    shouldEscalate = true;
    reason = 'keyword: ' + kw;
    break;
  }
}

// 2. Low confidence check or AI failure check
if (!shouldEscalate && aiResponse.confidence !== undefined) {
  const threshold = config.escalation_confidence_threshold || 0.3;
  if (aiResponse.confidence < threshold) {
    shouldEscalate = true;
    reason = 'low_confidence';
  }
}

// Extract response text
let replyText = aiResponse.text || aiResponse.choices?.[0]?.message?.content || '';
if (!replyText) {
  replyText = config.fallback_message || promptData.fallback_message || 'Maaf, saya belum bisa menjawab pertanyaan tersebut. Silakan hubungi admin toko.';
  if (!shouldEscalate) {
    shouldEscalate = true;
    reason = 'ai_gateway_fallback';
  }
}

return [{
  json: {
    should_escalate: shouldEscalate,
    reason: reason,
    response: replyText,
    tenant_id: promptData.tenant_id,
    customer_id: promptData.customer_id,
    channel: promptData.channel
  }
}];

